entries[68823] = { ["name"] = "Armored Razzashi Raptor", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The purebred royal raptors of Zul'Gurub, these mounts have become a rare sight in Stranglethorn Vale. The Gurubashi have been known to fly into a rage at the sight of any non-troll riding one of their precious beasts.\"\nDrop:\nBloodlord Mandokir\nZone:\nZul'Gurub" }
entries[68824] = { ["name"] = "Swift Zulian Panther", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The jungle trolls have long coveted panther fangs, using them for rituals or as ingredients in mojos.\"\nDrop:\nHigh Priestess Kilnara\nZone:\nZul'Gurub" }
entries[68825] = { ["name"] = "Amani Dragonhawk", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Dragonhawks liberated from troll enslavement are considered among the most loyal of all their kin.\"\nVendor:\nLandro Longshot\nLocation:\nBooty Bay" }
entries[68833] = { ["name"] = "Panther Cub", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your panther cub.\nRequires level 1 to 80 ( 80)" }
