entries[68890] = { ["name"] = "Dragon Kite 2-Pack", ["text"] = "Quest Item\nUnique\nUse: Fly dragon kites with your orphan. (30 Sec Cooldown)\nSell Price:" }
entries[68915] = { ["name"] = "Scales of Life", ["text"] = "Binds when equipped\nUnique-Equipped: Scales of Life (1)\nTrinket\n+6 Stamina\nEquip: Stores up to 511 additional health from spells which heal you for more than your maximum health.\nUse: Instantly release all health stored on the Scales of Life as a self-heal. (1 Min Cooldown)\nSell Price:" }
entries[68925] = { ["name"] = "Variable Pulse Lightning Capacitor", ["text"] = "Binds when picked up\nUnique-Equipped: Variable Pulse Lightning Capacitor (1)\nTrinket\n+4 Intellect\nEquip: You gain an Electrical Charge each time you cause a damaging spell critical strike, granting a chance to fire a Lightning Bolt for ( 9 * 0.875) to ( 9 * 1.125) damage per Electrical Charge accumulated. You cannot have more than 10 Electrical Charges and cannot gain one more often than once every 2.5 sec. (2.5s cooldown)\nSell Price:" }
entries[68926] = { ["name"] = "Jaws of Defeat", ["text"] = "Binds when picked up\nUnique-Equipped: Jaws of Defeat (1)\nTrinket\n+4 Intellect\nUse: Your next 10 spells cast within 20 sec will reduce the cost of your holy and nature spells by 1 , stacking up to 10 times. (900ms cooldown) (2 Min Cooldown)\nSell Price:" }
entries[68927] = { ["name"] = "The Hungerer", ["text"] = "Binds when picked up\nUnique-Equipped: The Hungerer (1)\nTrinket\n+4 Agility\nEquip: Your melee and ranged attacks have a chance to grant you 22 haste for 15 sec. (1m cooldown)\nSell Price:" }
entries[68937] = { ["name"] = "Direhammer's Boots", ["text"] = "Quest Item\nUnique\n\"These boots have seen better days.\"" }
entries[68955] = { ["name"] = "Totem of Tortolla", ["text"] = "Quest Item\nUnique\nUse: Ensconce yourself within an impenetrable shell for 10 seconds. (20 Sec Cooldown)" }
entries[68972] = { ["name"] = "Apparatus of Khaz'goroth", ["text"] = "Binds when equipped\nUnique-Equipped: Apparatus of Khaz'goroth (1)\nTrinket\n+4 Strength\nEquip: Your melee critical strikes grant Titanic Power, allowing you to power this device. Titanic Power stacks up to 5 times and lasts 30 sec.\nUse: Consume all Titanic Power to increase your critical strike, haste, or mastery by 5 per Titanic Power accumulated, lasting 15 sec. The apparatus will always choose the highest of those three values. (2 Min Cooldown)\nSell Price:" }
entries[68981] = { ["name"] = "Spidersilk Spindle", ["text"] = "Binds when picked up\nUnique-Equipped: Spidersilk Spindle (1)\nTrinket\n+ 6 Mastery\nEquip: Melee attacks which reduce you below 35% health cause you to gain a protective shield which absorbs 437 damage for 30 sec. Cannot occur more than once every 1 min. (1m cooldown)\nSell Price:" }
entries[68982] = { ["name"] = "Necromantic Focus", ["text"] = "Binds when picked up\nUnique-Equipped: Necromantic Focus (1)\nTrinket\n+4 Intellect\nEquip: Grants 1 mastery for 10 sec each time you deal periodic spell damage, stacking up to 10 times.\nSell Price:" }
entries[68983] = { ["name"] = "Eye of Blazing Power", ["text"] = "Binds when picked up\nUnique-Equipped: Eye of Blazing Power (1)\nTrinket\n+4 Intellect\nEquip: Your healing spells have a chance to instantly heal the most injured nearby party member for 87 . (Proc chance: 10%, 45s cooldown)\nSell Price:" }
entries[68994] = { ["name"] = "Matrix Restabilizer", ["text"] = "Binds when picked up\nUnique-Equipped: Matrix Restabilizer (1)\nTrinket\n+4 Agility\nEquip: Your melee and ranged attacks have a chance to grant 18 critical strike, haste, or mastery for 30 sec, whichever is currently highest. (Proc chance: 20%, 1.75m cooldown)\nSell Price:" }
entries[68995] = { ["name"] = "Vessel of Acceleration", ["text"] = "Binds when picked up\nUnique-Equipped: Vessel of Acceleration (1)\nTrinket\n+4 Strength\nEquip: Grants 1 critical strike for 20 sec each time you deal a melee critical strike, stacking up to 5 times.\nSell Price:" }
entries[68996] = { ["name"] = "Stay of Execution", ["text"] = "Binds when picked up\nUnique-Equipped: Stay of Execution (1)\nTrinket\n+ 6 Dodge\nUse: Absorbs 20% of incoming damage, up to 54 . After the effect ends, you take 8% of the damage absorbed every 2 sec for 10 sec. Lasts 30 sec. (2 Min Cooldown)\nRequires Avengers of Hyjal\n- Revered\nSell Price:" }
entries[68997] = { ["name"] = "Guardian's Staff", ["text"] = "Quest Item\nUse: Place into the Pile of Ash to summon Galenges." }
