entries[69109] = { ["name"] = "Scales of Life", ["text"] = "Heroic\nBinds when picked up\nUnique-Equipped: Scales of Life (1)\nTrinket\n+6 Stamina\nEquip: Stores up to 170 additional health from spells which heal you for more than your maximum health.\nUse: Instantly release all health stored on the Scales of Life as a self-heal. (1 Min Cooldown)\nSell Price:" }
entries[69110] = { ["name"] = "Variable Pulse Lightning Capacitor", ["text"] = "Heroic\nBinds when picked up\nUnique-Equipped: Variable Pulse Lightning Capacitor (1)\nTrinket\n+4 Intellect\nEquip: You gain an Electrical Charge each time you cause a damaging spell critical strike, granting a chance to fire a Lightning Bolt for ( 31 * 0.875) to ( 31 * 1.125) damage per Electrical Charge accumulated. You cannot have more than 10 Electrical Charges and cannot gain one more often than once every 2.5 sec. (2.5s cooldown)\nSell Price:" }
entries[69111] = { ["name"] = "Jaws of Defeat", ["text"] = "Heroic\nBinds when picked up\nUnique-Equipped: Jaws of Defeat (1)\nTrinket\n+4 Intellect\nUse: Your next 10 spells cast within 20 sec will reduce the cost of your holy and nature spells by 1 , stacking up to 10 times. (900ms cooldown) (2 Min Cooldown)\nSell Price:" }
entries[69112] = { ["name"] = "The Hungerer", ["text"] = "Heroic\nBinds when picked up\nUnique-Equipped: The Hungerer (1)\nTrinket\n+4 Agility\nEquip: Your melee and ranged attacks have a chance to grant you 23 haste for 15 sec. (59s cooldown)\nSell Price:" }
entries[69113] = { ["name"] = "Apparatus of Khaz'goroth", ["text"] = "Heroic\nBinds when picked up\nUnique-Equipped: Apparatus of Khaz'goroth (1)\nTrinket\n+4 Strength\nEquip: Your melee critical strikes grant Titanic Power, allowing you to power this device. Titanic Power stacks up to 5 times and lasts 30 sec.\nUse: Consume all Titanic Power to increase your critical strike, haste, or mastery by 5 per Titanic Power accumulated, lasting 15 sec. The apparatus will always choose the highest of those three values. (2 Min Cooldown)\nSell Price:" }
entries[69138] = { ["name"] = "Spidersilk Spindle", ["text"] = "Heroic\nBinds when picked up\nUnique-Equipped: Spidersilk Spindle (1)\nTrinket\n+ 6 Mastery\nEquip: Melee attacks which reduce you below 35% health cause you to gain a protective shield which absorbs 16 damage for 30 sec. Cannot occur more than once every 1 min. (1m cooldown)\nSell Price:" }
